def _is_valid_shorthand_name(name: object) -> bool:
    """Check that a shorthand name has an option prefix followed by at
    least one character, and contains no ``=`` and no whitespace.
    """
    if not isinstance(name, str):
        return False

    prefix, rest = _split_opt(name)

    if not prefix or not rest:
        return False

    return "=" not in name and not any(ch.isspace() for ch in name)


class Shorthand:
    """A token that a command's option parser replaces in place by a
    fixed sequence of tokens, which are then processed as if they had
    been typed at that position.

    :param name: The shorthand token, with an option prefix, like ``-q``.
    :param expansion: The tokens the shorthand stands for.
    :param help: Help text shown in the ``Shorthands`` help section and
        in shell completion.
    :param hidden: Hide the shorthand from the help page and from shell
        completion of option names.

    .. versionadded:: 8.6.0
    """

    name: str
    expansion: tuple[str, ...]
    help: str | None
    hidden: bool

    def __init__(
        self,
        name: str,
        expansion: cabc.Sequence[str],
        help: str | None = None,
        hidden: bool = False,
    ) -> None:
        if not _is_valid_shorthand_name(name):
            raise ValueError(f"Invalid shorthand name {name!r}.")

        if isinstance(expansion, str):
            raise TypeError(
                "Shorthand expansion must be a sequence of strings, not a"
                " single string."
            )

        tokens = tuple(expansion)

        if not all(isinstance(token, str) for token in tokens):
            raise TypeError("Shorthand expansion tokens must be strings.")

        if not tokens:
            raise ValueError(f"Shorthand {name!r} must expand to at least one token.")

        self.name = name
        self.expansion = tokens
        self.help = help
        self.hidden = hidden

    def to_info_dict(self) -> dict[str, t.Any]:
        """Gather information that could be useful for a tool generating
        user-facing documentation.
        """
        return {
            "name": self.name,
            "expansion": list(self.expansion),
            "help": self.help,
            "hidden": self.hidden,
        }

    def __repr__(self) -> str:
        return f"<{self.__class__.__name__} {self.name}>"


