def _make_plain_cli():
    @click.command()
    @click.option("--log-level", default="info")
    @click.option("--color/--no-color", default=True)
    @click.shorthand("-q", "--log-level", "error", "--no-color", help="Quiet mode.")
    @click.shorthand("-L", "--log-level")
    def cli(log_level, color):
        click.echo(f"log_level={log_level} color={color}")

    return cli


def _make_choice_cli():
    @click.command()
    @click.option(
        "--log-level", type=click.Choice(["debug", "error", "info"]), default="info"
    )
    @click.option("--color/--no-color", default=True)
    @click.shorthand("-q", "--log-level", "error", "--no-color", help="Quiet mode.")
    @click.shorthand("-L", "--log-level")
    @click.shorthand("--debug-all", "--log-level", "debug", hidden=True)
    def cli(log_level, color):
        click.echo(f"log_level={log_level} color={color}")

    return cli


def _make_tool():
    @click.group()
    @click.option("--profile", type=click.Choice(["dev", "prod"]), default="dev")
    @click.shorthand("-D", "--profile", "prod", "deploy")
    @click.shorthand("-P", "--profile")
    def tool(profile):
        click.echo(f"profile={profile}")

    @tool.command()
    @click.option("--dry-run", is_flag=True)
    @click.shorthand("-n", "--dry-run")
    def deploy(dry_run):
        click.echo(f"dry_run={dry_run}")

    return tool


SINGLE_STR = "Shorthand expansion must be a sequence of strings, not a single string."


@pytest.mark.parametrize(
    ("name", "expansion", "exc_type", "message"),
    [
        ("q", ["--x"], ValueError, "Invalid shorthand name 'q'."),
        ("--", ["--x"], ValueError, "Invalid shorthand name '--'."),
        ("-", ["--x"], ValueError, "Invalid shorthand name '-'."),
        ("-q=x", ["--x"], ValueError, "Invalid shorthand name '-q=x'."),
        ("-q x", ["--x"], ValueError, "Invalid shorthand name '-q x'."),
        (5, ["--x"], ValueError, "Invalid shorthand name 5."),
        ("q", "--x", ValueError, "Invalid shorthand name 'q'."),
        ("-q", "--x", TypeError, SINGLE_STR),
        ("-q", "", TypeError, SINGLE_STR),
        ("-q", ["--x", 1], TypeError, "Shorthand expansion tokens must be strings."),
        ("-q", [1], TypeError, "Shorthand expansion tokens must be strings."),
        ("-q", [], ValueError, "Shorthand '-q' must expand to at least one token."),
        (
            "--quiet",
            (),
            ValueError,
            "Shorthand '--quiet' must expand to at least one token.",
        ),
    ],
)
def test_shorthand_validation_messages(name, expansion, exc_type, message):
    from click import Shorthand

    with pytest.raises(exc_type) as exc_info:
        Shorthand(name, expansion)

    assert type(exc_info.value) is exc_type
    assert str(exc_info.value) == message


def test_shorthand_attributes_repr_and_info_dict():
    from click import Shorthand
    from click import shorthand

    sh = Shorthand("-q", ["--a", "b"], help="Quiet.")
    assert sh.name == "-q"
    assert sh.expansion == ("--a", "b")
    assert sh.help == "Quiet."
    assert sh.hidden is False
    assert repr(sh) == "<Shorthand -q>"
    assert sh.to_info_dict() == {
        "name": "-q",
        "expansion": ["--a", "b"],
        "help": "Quiet.",
        "hidden": False,
    }

    hidden = Shorthand("+x", ("--a",), hidden=True)
    assert hidden.to_info_dict() == {
        "name": "+x",
        "expansion": ["--a"],
        "help": None,
        "hidden": True,
    }

    with pytest.raises(ValueError) as exc_info:
        shorthand("-q")

    assert str(exc_info.value) == "Shorthand '-q' must expand to at least one token."


def test_registration_order_and_type_check():
    from click import Shorthand

    @click.command(shorthands=[Shorthand("-a", ["--x", "a"])])
    @click.option("--x")
    @click.shorthand("-b", "--x", "b")
    @click.shorthand("-c", "--x", "c")
    def cli(x):
        pass

    assert [sh.name for sh in cli.shorthands] == ["-a", "-b", "-c"]

    click.shorthand("-d", "--x", "d")(cli)
    assert [sh.name for sh in cli.shorthands] == ["-a", "-b", "-c", "-d"]

    assert click.Command("plain").shorthands == []

    with pytest.raises(TypeError) as exc_info:
        click.Command("bad", shorthands=[Shorthand("-a", ["--x"]), "-q"])

    assert str(exc_info.value) == "'shorthands' must contain only Shorthand instances."

    with pytest.raises(TypeError) as exc_info:
        click.Group("bad", shorthands=["-q"])

    assert str(exc_info.value) == "'shorthands' must contain only Shorthand instances."


def test_expansion_is_processed_as_if_typed(runner):
    cli = _make_plain_cli()
    cases = [
        (["-q"], "log_level=error color=False\n"),
        (["-q", "--log-level", "debug"], "log_level=debug color=False\n"),
        (["--log-level", "-q"], "log_level=-q color=True\n"),
        (["-L", "-q"], "log_level=-q color=True\n"),
        (["-L", "debug", "-q"], "log_level=error color=False\n"),
        (["--color", "-q", "--color"], "log_level=error color=True\n"),
    ]

    for args, expected in cases:
        result = runner.invoke(cli, args)
        assert result.exit_code == 0, (args, result.output)
        assert result.output == expected, args

    result = runner.invoke(cli, ["-L"])
    assert result.exit_code == 2
    assert result.output.splitlines()[-1] == (
        "Error: Option '--log-level' requires an argument."
    )

    result = runner.invoke(cli, ["--", "-q"])
    assert result.exit_code == 2
    assert result.output == (
        "Usage: cli [OPTIONS]\n"
        "Try 'cli --help' for help.\n"
        "\n"
        "Error: Got unexpected extra argument (-q)\n"
    )

    result = runner.invoke(_make_choice_cli(), ["-L", "-q"])
    assert result.exit_code == 2
    assert result.output.splitlines()[-1] == (
        "Error: Invalid value for '--log-level': '-q' is not one of"
        " 'debug', 'error', 'info'."
    )


