@pytest.mark.parametrize(
    ("option", "names", "normalize", "message"),
    [
        ("--x", ["-a", "-b", "-a"], False, "Shorthand '-a' is defined more than once."),
        (
            "--x",
            ["-a", "--x", "-a"],
            False,
            "Shorthand '--x' conflicts with an option of the same name.",
        ),
        ("--x", ["-Q", "-q"], True, "Shorthand '-q' is defined more than once."),
        (
            "--quiet",
            ["--QUIET"],
            True,
            "Shorthand '--QUIET' conflicts with an option of the same name.",
        ),
        ("--quiet", ["--QUIET"], False, None),
    ],
)
def test_conflict_and_duplicate_outcomes(runner, option, names, normalize, message):
    from click import Shorthand

    settings = {"token_normalize_func": str.lower} if normalize else {}
    cmd = click.Command(
        "cli",
        context_settings=settings,
        params=[click.Option([option], is_flag=True)],
        shorthands=[Shorthand(name, [option]) for name in names],
        callback=lambda **kwargs: click.echo(repr(kwargs)),
    )

    if message is None:
        result = runner.invoke(cmd, ["--QUIET"])
        assert result.exit_code == 0, result.output
        assert result.output == "{'quiet': True}\n"
        return

    with pytest.raises(ValueError) as exc_info:
        cmd.main([], standalone_mode=False)

    assert str(exc_info.value) == message


def test_conflicts_are_reported_whenever_the_command_parses(runner):
    from click import Shorthand

    message = "Shorthand '--no-color' conflicts with an option of the same name."

    def build(**kwargs):
        return click.Command(
            "cli",
            params=[click.Option(["--color/--no-color"])],
            shorthands=[Shorthand("--no-color", ["--color"])],
            **kwargs,
        )

    cmd = build()

    for args in (["--help"], ["--bogus"], []):
        result = runner.invoke(cmd, args)
        assert type(result.exception) is ValueError, args
        assert str(result.exception) == message
        assert result.output == ""

    with pytest.raises(ValueError) as exc_info:
        cmd.make_context("cli", ["--color"], resilient_parsing=True)

    assert str(exc_info.value) == message

    with pytest.raises(ValueError) as exc_info:
        cmd.make_parser(click.Context(cmd))

    assert str(exc_info.value) == message

    with pytest.raises(ValueError) as exc_info:
        _complete(cmd, [], "-")

    assert str(exc_info.value) == message

    result = runner.invoke(build(no_args_is_help=True), [])
    assert type(result.exception) is ValueError
    assert str(result.exception) == message
    assert result.output == ""

    group = click.Group(
        "grp",
        params=[click.Option(["--x"])],
        shorthands=[Shorthand("--x", ["--x", "1"])],
    )
    result = runner.invoke(group, [])
    assert type(result.exception) is ValueError
    assert str(result.exception) == (
        "Shorthand '--x' conflicts with an option of the same name."
    )


